!function(){"use strict";window.cloneData=function(n){return null==n?n:JSON.parse(JSON.stringify(n))},window.stableStringify=function(n){return Array.isArray(n)?"["+n.map(window.stableStringify).join(",")+"]":n&&"object"==typeof n?"{"+Object.keys(n).sort().map(t=>JSON.stringify(t)+":"+window.stableStringify(n[t])).join(",")+"}":JSON.stringify(n)},window.notify=function(n,t){var i=document.getElementById("app_notification");i&&(i.textContent=n,i.className="app-notification "+(t||"success"),window.clearTimeout(window.__notificationTimer),window.__notificationTimer=window.setTimeout(function(){i.classList.add("hidden")},3500))},window.getRouteName=function(){var n=location.pathname.split("/").filter(Boolean);return n.length>1?decodeURIComponent(n[1]):""},window.getRouteId=window.getRouteName}();